fn read_request<R: Read>(reader: &mut BufReader<R>) -> io::Result<Option<RemoteRequest>> {
    let mut line = String::new();
    if reader.read_line(&mut line)? == 0 {
        return Ok(None);
    }
    let mut parts = line.split_whitespace();
    let (Some(method), Some(target)) = (parts.next(), parts.next()) else {
        return Err(io::Error::new(
            io::ErrorKind::InvalidData,
            "bad request line",
        ));
    };
    let mut headers: Vec<(String, String)> = Vec::new();
    let mut total = line.len();
    loop {
        let mut h = String::new();
        if reader.read_line(&mut h)? == 0 {
            return Err(io::Error::new(io::ErrorKind::UnexpectedEof, "headers cut"));
        }
        total += h.len();
        if total > MAX_HEAD {
            return Err(io::Error::new(io::ErrorKind::InvalidData, "head too large"));
        }
        let h = h.trim_end();
        if h.is_empty() {
            break;
        }
        if let Some((n, v)) = h.split_once(':') {
            headers.push((n.trim().to_ascii_lowercase(), v.trim().to_owned()));
        }
    }
    let header = |name: &str| {
        headers
            .iter()
            .find(|(n, _)| n == name)
            .map(|(_, v)| v.as_str())
    };
    let length: usize = header("content-length")
        .and_then(|v| v.parse().ok())
        .unwrap_or(0);
    if length > MAX_BODY {
        return Err(io::Error::new(io::ErrorKind::InvalidData, "body too large"));
    }
    let bearer = header("authorization")
        .and_then(|v| v.strip_prefix("Bearer "))
        .map(|t| t.trim().to_owned())
        .filter(|t| !t.is_empty());
    let upgrade = header("upgrade")
        .filter(|u| u.eq_ignore_ascii_case("websocket"))
        .and_then(|_| header("sec-websocket-key"))
        .map(str::to_owned);
    let (path, query) = target.split_once('?').unwrap_or((target, ""));
    let query = query
        .split('&')
        .filter(|s| !s.is_empty())
        .map(|pair| {
            let (n, v) = pair.split_once('=').unwrap_or((pair, ""));
            (n.to_owned(), v.to_owned())
        })
        .collect();
    let mut body = vec![0; length];
    reader.read_exact(&mut body)?;
    Ok(Some(RemoteRequest {
        method: method.to_owned(),
        path: path.to_owned(),
        query,
        body,
        bearer,
        upgrade,
    }))
}

/// The 101 that switches a connection to WebSocket. The request was
/// already read by `read_request`, so `tungstenite::accept` cannot be
/// used; the stream is wrapped with `from_raw_socket` after this.
fn respond_upgrade<W: Write>(w: &mut W, key: &str) -> io::Result<()> {
    write!(
        w,
        "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Accept: {}\r\n\r\n",
        tungstenite::handshake::derive_accept_key(key.as_bytes())
    )?;
    w.flush()
}

/// Write one response. Head and body in one write, so a reply is one
/// TLS record and one segment.
fn respond<W: Write>(w: &mut W, status: u16, body: &[u8]) -> io::Result<()> {
    let reason = match status {
        200 => "OK",
        400 => "Bad Request",
        401 => "Unauthorized",
        403 => "Forbidden",
        404 => "Not Found",
        405 => "Method Not Allowed",
        413 => "Content Too Large",
        429 => "Too Many Requests",
        503 => "Service Unavailable",
        504 => "Gateway Timeout",
        _ => "Error",
    };
    let mut out = format!(
        "HTTP/1.1 {status} {reason}\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: keep-alive\r\n\r\n",
        body.len()
    )
    .into_bytes();
    out.extend_from_slice(body);
    w.write_all(&out)?;
    w.flush()
}

/// The error body the connection thread sends for what never reaches
/// the frame.
fn error_body(code: &str, message: &str) -> Vec<u8> {
    serde_json::json!({ "error": { "code": code, "message": message } })
        .to_string()
        .into_bytes()
}
fn connection(tcp: TcpStream, shared: &Arc<Shared>, paired: &AtomicBool) -> io::Result<()> {
    tcp.set_read_timeout(Some(HANDSHAKE_TIMEOUT))?;
    tcp.set_write_timeout(Some(WRITE_TIMEOUT))?;
    // A reply is one record and goes out at once; Nagle with the
    // device's delayed ACK would otherwise add milliseconds per request.
    tcp.set_nodelay(true)?;
    let conn = ServerConnection::new(Arc::clone(&shared.tls)).map_err(io::Error::other)?;
    let mut stream = StreamOwned::new(conn, tcp);
    while stream.conn.is_handshaking() {
        stream.conn.complete_io(&mut stream.sock)?;
    }
    let mut reader = BufReader::new(stream);
    let mut first = true;
    while let Some(request) = read_request(&mut reader)? {
        if first {
            reader.get_ref().sock.set_read_timeout(Some(IDLE_TIMEOUT))?;
            first = false;
        }
        if shared.limits.limited(&request.path) {
            respond(
                reader.get_mut(),
                429,
                &error_body("rate_limited", "too many requests; try again in a minute"),
            )?;
            continue;
        }
        let (reply_tx, reply_rx) = mpsc::sync_channel(1);
        let upgrade_key = request.upgrade.clone();
        let mut queue = None;
        let queue_for_frame = upgrade_key.as_ref().map(|_| {
            let (q_tx, q_rx) = mpsc::sync_channel::<String>(SUBSCRIBER_QUEUE);
            let overflow = Arc::new(AtomicBool::new(false));
            let id = shared.next_subscriber.fetch_add(1, Ordering::SeqCst);
            queue = Some((id, q_rx, Arc::clone(&overflow)));
            SubscriberQueue {
                id,
                tx: q_tx,
                overflow,
            }
        });
        if shared
            .requests
            .try_send(RemoteIncoming {
                request,
                reply: reply_tx,
                subscriber: queue_for_frame,
            })
            .is_err()
        {
            respond(
                reader.get_mut(),
                503,
                &error_body("busy", "the host is busy; try again"),
            )?;
            continue;
        }
        (shared.wake)();
        let reply = match reply_rx.recv_timeout(ANSWER_TIMEOUT) {
            Ok(reply) => reply,
            Err(_) => RemoteReply {
                status: 504,
                body: error_body("no_answer", "the app did not answer in time"),
                authenticated: false,
            },
        };
        if reply.authenticated && !paired.load(Ordering::SeqCst) {
            // The device moves from the unauthenticated pool to the
            // paired one on its first authenticated request.
            if shared.pools.paired.load(Ordering::SeqCst) >= MAX_PAIRED {
                respond(
                    reader.get_mut(),
                    503,
                    &error_body("full", "too many paired connections"),
                )?;
                return Ok(());
            }
            shared.pools.paired.fetch_add(1, Ordering::SeqCst);
            shared.pools.unauthenticated.fetch_sub(1, Ordering::SeqCst);
            paired.store(true, Ordering::SeqCst);
        }
        if reply.status == SUBSCRIBED
            && let (Some(key), Some((id, q_rx, overflow))) = (upgrade_key, queue)
        {
            respond_upgrade(reader.get_mut(), &key)?;
            let out = subscriber(reader.into_inner(), &q_rx, &overflow, id, shared);
            let ended = SubscriberFrame {
                subscriber: id,
                text: None,
            };
            if shared.frames.send(ended).is_ok() {
                (shared.wake)();
            }
            return out;
        }
        respond(reader.get_mut(), reply.status, &reply.body)?;
    }
    Ok(())
}

